//! GPIO (General Purpose I/O)
//!
//! Type-safe, ownership-based GPIO for the CH32X035's GPIOA/GPIOB/GPIOC
//! ports. A pin is represented by the zero-sized type [`Pin<PORT, N>`], where
//! `PORT` selects the port (0 = A, 1 = B, 2 = C) and `N` the pin number.
//!
//! Following the rp2350 style, each pin gets its own concrete `impl`
//! generated by the `impl_pin!` macro, which references the PAC's generated
//! per-pin field constants (e.g. `gpioa::Cfglr::MODE0_OFFSET`, `Bshr::BS0`)
//! instead of hand-written register offsets.
//!
//! # Ownership model
//!
//! [`Pins`] owns the GPIO ports. Pins are created from it with
//! [`Pins::pa`]/[`Pins::pb`]/[`Pins::pc`]. Each `Pin<N>` is `!Sync` (like
//! rp2350) — create each pin token only once.
//!
//! # Example
//!
//! ```ignore
//! use ch32x035::{Rcc, gpio::Pins};
//!
//! let mut rcc = Rcc::new(dp.RCC);
//! let pins = Pins::init(dp.GPIOA, dp.GPIOB, dp.GPIOC, &mut rcc);
//! let mut led = pins.pa::<0>();
//! led.into_output();
//! led.set_high();
//! ```
//!
//! # Package selection
//!
//! The CH32X035 is sold in several packages that bond out different subsets
//! of the 60 GPIO pins. Enable exactly one sub-model cargo feature (see
//! [`crate::package`]) and [`Pins::pa`]/[`Pins::pb`]/[`Pins::pc`] will only
//! accept pins that physically exist on the chosen package, rejecting
//! un-bonded pins at compile time.
//!
//! # Runtime-indexed access
//!
//! Like the rp2350 HAL, the [`get`], [`output`], [`set_high`], [`set_low`],
//! [`toggle`], [`set`] and `into_*` free functions operate on a GPIO by a
//! `(port, pin)` tuple instead of the compile-time [`Pin<PORT, N>`] type
//! (`port`: 0 = A, 1 = B, 2 = C; `pin`: 0..=23). These are `unsafe`: the
//! caller must ensure the ports are initialized and that no data races occur.
//! The `(port, pin)` argument is validated against the selected package at
//! runtime.

use core::marker::PhantomData;

use crate::Steal;
use crate::pac;
use crate::rcc::{Apb2Periph, Rcc};

/// GPIO port ownership container.
pub struct Pins {
    _gpioa: pac::GPIOA,
    _gpiob: pac::GPIOB,
    _gpioc: pac::GPIOC,
}

impl Pins {
    /// Create the pin container, enabling and resetting the GPIO ports.
    ///
    /// Consumes the GPIO peripherals and the AFIO clock.
    pub fn init(gpioa: pac::GPIOA, gpiob: pac::GPIOB, gpioc: pac::GPIOC, rcc: &mut Rcc) -> Self {
        // Enable the port clocks and reset the ports to a known state
        let ports = Apb2Periph::Iopa | Apb2Periph::Iopb | Apb2Periph::Iopc | Apb2Periph::Afio;
        rcc.apb2_reset(ports);
        rcc.apb2_clear_reset(ports);
        rcc.apb2_enable(ports);

        Self {
            _gpioa: gpioa,
            _gpiob: gpiob,
            _gpioc: gpioc,
        }
    }

    /// Obtain a handle without ownership checks.
    ///
    /// # Safety
    ///
    /// The caller must ensure the GPIO ports have been initialized and that no
    /// data races occur.
    #[inline]
    pub unsafe fn steal() -> Steal<Self> {
        Steal(Self {
            _gpioa: unsafe { pac::GPIOA::steal() },
            _gpiob: unsafe { pac::GPIOB::steal() },
            _gpioc: unsafe { pac::GPIOC::steal() },
        })
    }

    /// Create a pin token for GPIO port A, pin `N`.
    ///
    /// Only pins bonded out on the selected package (cargo feature) are
    /// accepted; this is checked at compile time.
    #[inline]
    pub fn pa<const N: u32>(&self) -> Pin<0, N> {
        const {
            assert!(
                crate::package::pin_available::<0, N>(),
                "PA pin is not bonded out on the selected CH32X035 package"
            );
        }
        Pin::new()
    }

    /// Create a pin token for GPIO port B, pin `N`.
    ///
    /// Only pins bonded out on the selected package (cargo feature) are
    /// accepted; this is checked at compile time.
    #[inline]
    pub fn pb<const N: u32>(&self) -> Pin<1, N> {
        const {
            assert!(
                crate::package::pin_available::<1, N>(),
                "PB pin is not bonded out on the selected CH32X035 package"
            );
        }
        Pin::new()
    }

    /// Create a pin token for GPIO port C, pin `N`.
    ///
    /// Only pins bonded out on the selected package (cargo feature) are
    /// accepted; this is checked at compile time.
    #[inline]
    pub fn pc<const N: u32>(&self) -> Pin<2, N> {
        const {
            assert!(
                crate::package::pin_available::<2, N>(),
                "PC pin is not bonded out on the selected CH32X035 package"
            );
        }
        Pin::new()
    }
}

/// A single GPIO pin (zero-sized, type-state token).
///
/// `PORT`: 0 = A, 1 = B, 2 = C. `N`: pin number 0..=15.
///
/// `Pin` is `Send` but **not** `Sync`: only one task should own a given pin.
pub struct Pin<const PORT: u32, const N: u32> {
    _marker: PhantomData<*const ()>,
}

unsafe impl<const PORT: u32, const N: u32> Send for Pin<PORT, N> {}

impl<const PORT: u32, const N: u32> Pin<PORT, N> {
    /// The pin number
    #[inline]
    pub const fn pin_number() -> u32 {
        N
    }

    /// The port number (0 = A, 1 = B, 2 = C)
    #[inline]
    pub const fn port_number() -> u32 {
        PORT
    }

    /// Create a new pin token (used internally by `Pins`).
    ///
    /// Fails to compile if `(PORT, N)` is not bonded out on the selected
    /// package.
    const fn new() -> Self {
        const {
            assert!(
                crate::package::pin_available::<PORT, N>(),
                "GPIO pin (port, n) is not bonded out on the selected CH32X035 package"
            );
        }
        Self {
            _marker: PhantomData,
        }
    }

    /// Obtain a `Pin<PORT, N>` handle without ownership checks.
    ///
    /// Useful in interrupt context, where the pins are owned by `main()` and
    /// not accessible. The data-plane methods ([`set_high`](Self::set_high),
    /// [`set_low`](Self::set_low), [`toggle`](Self::toggle), …) take `&self`,
    /// so a stolen handle can drive the pin directly.
    ///
    /// Fails to compile if `(PORT, N)` is not bonded out on the selected
    /// package.
    ///
    /// # Safety
    ///
    /// The caller must ensure the GPIO ports have been initialized (e.g. via
    /// [`Pins::init`]) and that no data races occur — i.e. the same pin is not
    /// being reconfigured concurrently from another context.
    #[inline]
    pub const unsafe fn steal() -> Steal<Self> {
        const {
            assert!(
                crate::package::pin_available::<PORT, N>(),
                "GPIO pin (port, n) is not bonded out on the selected CH32X035 package"
            );
        }
        Steal(Self {
            _marker: PhantomData,
        })
    }
}

// =============================================================================
// Per-pin implementations
// =============================================================================
//
// Each pin number gets a concrete `impl Pin<PORT, N>` generated by the
// `impl_pin!` macro. The macro uses `pastey!` to build the PAC's generated
// field accessor names (`write_mode{N}`, `write_cnf{N}`, `trigger_bs{N}`,
// `trigger_br{N}`, `idr{N}`, `odr{N}`), so all register access goes through
// `ch32x035-pac` instead of hand-written offsets and masks (rp2350 style).
//
// Pins 0-7 are configured through `CFGLR`, pins 8-15 through `CFGHR`, and
// pins 16-23 through `CFGXR`. Pins 0-15 set/reset through `BSHR`, pins
// 16-23 through `BSXR`. The set/reset bits are write-only, hence the
// `trigger_*` accessors.

/// CNF field value (output mode): general-purpose push-pull output
const CNF_OUTPUT_PUSHPULL: u32 = 0b00;
/// CNF field value (output mode): alternate-function push-pull output.
///
/// I2C and USB-PD automatically switch the driver to open-drain, so this is
/// also the correct configuration for I2C pins. The reference manual does
/// not define separate open-drain CNF values (`01`/`11` are reserved).
const CNF_ALT_PUSHPULL: u32 = 0b10;
/// CNF field value (input mode): analog input
const CNF_INPUT_ANALOG: u32 = 0b00;
/// CNF field value (input mode): floating input
const CNF_INPUT_FLOATING: u32 = 0b01;
/// CNF field value (input mode): pull-up/pull-down input
const CNF_INPUT_PULL: u32 = 0b10;
/// MODE field value: input mode
const MODE_INPUT: u32 = 0b00;
/// MODE field value: output mode.
///
/// The manual defines `01`/`10`/`11` as output mode (there is no speed
/// selection on this chip); `01` matches the official SDK.
const MODE_OUTPUT: u32 = 0b01;

/// Generate the register-access methods for one pin of one port.
///
/// `$cfg` is the config register field (`cfglr` for pins 0-7, `cfghr` for
/// pins 8-15, `cfgxr` for pins 16-23); `$bs` is the set/reset register field
/// (`bshr` for pins 0-15, `bsxr` for pins 16-23); `$base` is the port base
/// from the PAC (`gpioa::BASE`).
macro_rules! impl_pin {
    ($port:expr, $n:tt, $cfg:ident, $bs:ident, $base:expr) => {
        pastey::paste! {
            impl Pin<$port, $n> {
                /// Pointer to this pin's GPIO register block.
                ///
                /// All ports share the same register layout, so the
                /// `gpioa::RegisterBlock` type is used for every port.
                const fn regs() -> &'static pac::gpioa::RegisterBlock {
                    // SAFETY: `$base` is a valid GPIO port base and the block
                    // is only reachable through this type-state `Pin` token.
                    unsafe { &*($base as *const pac::gpioa::RegisterBlock) }
                }

                /// Set the CNF/MODE fields using the PAC accessors.
                #[inline(always)]
                fn set_config(cnf: u32, mode: u32) {
                    let regs = Self::regs();
                    regs.$cfg.[<write_mode $n>](mode);
                    regs.$cfg.[<write_cnf $n>](cnf);
                }

                // =========================================================
                // Output configuration
                // =========================================================

                /// Configure the pin as a push-pull output
                #[inline]
                pub fn into_output(&mut self) {
                    Self::set_config(CNF_OUTPUT_PUSHPULL, MODE_OUTPUT);
                }

                /// Configure the pin as an alternate-function push-pull output
                /// (used by on-chip peripherals).
                ///
                /// I2C and USB-PD automatically switch the output driver to
                /// open-drain, so this single configuration covers all
                /// on-chip peripherals; the chip has no separate open-drain
                /// alternate-function mode.
                #[inline]
                pub fn into_alt_push_pull(&mut self) {
                    Self::set_config(CNF_ALT_PUSHPULL, MODE_OUTPUT);
                }

                /// Set the pin output high
                #[inline(always)]
                pub fn set_high(&self) {
                    Self::regs().$bs.[<trigger_bs $n>]();
                }

                /// Set the pin output low
                #[inline(always)]
                pub fn set_low(&self) {
                    Self::regs().$bs.[<trigger_br $n>]();
                }

                /// Toggle the pin output
                #[inline(always)]
                pub fn toggle(&self) {
                    let regs = Self::regs();
                    if regs.outdr.[<odr $n>]() {
                        regs.outdr.[<clr_odr $n>]();
                    } else {
                        regs.outdr.[<set_odr $n>]();
                    }
                }

                /// Get the current output data value of the pin
                #[inline(always)]
                pub fn is_output_high(&self) -> bool {
                    Self::regs().outdr.[<odr $n>]()
                }

                // =========================================================
                // Input configuration
                // =========================================================

                /// Configure the pin as a floating input
                #[inline]
                pub fn into_input(&mut self) {
                    Self::set_config(CNF_INPUT_FLOATING, MODE_INPUT);
                }

                /// Configure the pin as a pull-up input
                #[inline]
                pub fn into_input_pullup(&mut self) {
                    Self::set_config(CNF_INPUT_PULL, MODE_INPUT);
                    // Set the output data bit to select pull-up
                    // (1 = pull-up, 0 = pull-down)
                    Self::regs().outdr.[<set_odr $n>]();
                }

                /// Configure the pin as a pull-down input.
                ///
                /// Note: only PA0..=PA15 and PC16..=PC17 support a pull-down
                /// resistor; on every other pin the pull-down is unavailable.
                #[inline]
                pub fn into_input_pulldown(&mut self) {
                    Self::set_config(CNF_INPUT_PULL, MODE_INPUT);
                    Self::regs().outdr.[<clr_odr $n>]();
                }

                /// Configure the pin as an analog input
                #[inline]
                pub fn into_analog(&mut self) {
                    Self::set_config(CNF_INPUT_ANALOG, MODE_INPUT);
                }

                /// Read the pin's input value
                #[inline(always)]
                pub fn is_high(&self) -> bool {
                    Self::regs().indr.[<idr $n>]()
                }

                /// Read the pin's input value
                #[inline(always)]
                pub fn is_low(&self) -> bool {
                    !self.is_high()
                }
            }
        }
    };
}

/// Generate pins 0-7 (configured through `CFGLR`, set/reset through `BSHR`).
macro_rules! impl_pins_low {
    ($port:expr, $base:expr, $($n:tt),+) => {
        $(impl_pin!($port, $n, cfglr, bshr, $base);)+
    };
}

/// Generate pins 8-15 (configured through `CFGHR`, set/reset through `BSHR`).
macro_rules! impl_pins_high {
    ($port:expr, $base:expr, $($n:tt),+) => {
        $(impl_pin!($port, $n, cfghr, bshr, $base);)+
    };
}

/// Generate pins 16-23 (configured through `CFGXR`, set/reset through `BSXR`).
macro_rules! impl_pins_ext {
    ($port:expr, $base:expr, $($n:tt),+) => {
        $(impl_pin!($port, $n, cfgxr, bsxr, $base);)+
    };
}

// Port A: PA0..=PA23
impl_pins_low!(0, pac::gpioa::BASE, 0, 1, 2, 3, 4, 5, 6, 7);
impl_pins_high!(0, pac::gpioa::BASE, 8, 9, 10, 11, 12, 13, 14, 15);
impl_pins_ext!(0, pac::gpioa::BASE, 16, 17, 18, 19, 20, 21, 22, 23);
// Port B: PB0..=PB21
impl_pins_low!(1, pac::gpiob::BASE, 0, 1, 2, 3, 4, 5, 6, 7);
impl_pins_high!(1, pac::gpiob::BASE, 8, 9, 10, 11, 12, 13, 14, 15);
impl_pins_ext!(1, pac::gpiob::BASE, 16, 17, 18, 19, 20, 21);
// Port C: PC0..=PC7 and PC14..=PC19 (PC8..=PC13 and PC20+ are not bonded out)
impl_pins_low!(2, pac::gpioc::BASE, 0, 1, 2, 3, 4, 5, 6, 7);
impl_pins_high!(2, pac::gpioc::BASE, 14, 15);
impl_pins_ext!(2, pac::gpioc::BASE, 16, 17, 18, 19);

// =============================================================================
// Runtime-indexed GPIO access (free functions)
// =============================================================================
//
// Like the rp2350 HAL, these functions operate on a GPIO by a `(port, pin)`
// tuple instead of the compile-time `Pin<PORT, N>` type.
//
// - `port`: 0 = A, 1 = B, 2 = C.
// - `pin`: pin number within the port, 0..=23 (PA0..=PA23, PB0..=PB21,
//   PC0..=PC7 and PC14..=PC19 are bonded out on some packages).
//
// # Safety
//
// Every function is `unsafe` because the caller must ensure the GPIO ports
// have been initialized via [`Pins::init`] and that no concurrent
// configuration changes happen while the operation is in flight. The
// `(port, pin)` argument is range-checked and validated against the selected
// package at runtime (panicking on an invalid pin).

/// Register block of the given port (all ports share the same layout).
#[inline]
fn port_regs(port: u32) -> &'static pac::gpioa::RegisterBlock {
    let base = match port {
        0 => pac::gpioa::BASE,
        1 => pac::gpiob::BASE,
        2 => pac::gpioc::BASE,
        _ => unreachable!("assert_pin guarantees port 0..=2"),
    };
    // SAFETY: `base` is a valid GPIO port base; the caller upholds the safety
    // contract (ports initialized, no data races).
    unsafe { &*(base as *const pac::gpioa::RegisterBlock) }
}

/// Assert that `(port, pin)` refers to a valid GPIO pin bonded out on the
/// selected package.
#[inline(always)]
fn assert_pin(port: u32, pin: u32) {
    assert!(
        crate::package::pin_available_runtime(port, pin),
        "GPIO (port {port}, pin {pin}) is not bonded out on the selected CH32X035 package"
    );
}

/// Pointer to the CNF/MODE register of a port pin and its 4-bit field shift.
#[inline]
fn cfg_reg(regs: &'static pac::gpioa::RegisterBlock, idx: u32) -> (*mut u32, u32) {
    match idx {
        0..=7 => (regs.cfglr.as_ptr(), 4 * idx),
        8..=15 => (regs.cfghr.as_ptr(), 4 * (idx - 8)),
        _ => (regs.cfgxr.as_ptr(), 4 * (idx - 16)),
    }
}

/// Set the CNF/MODE fields of a port pin (CFGLR/CFGHR/CFGXR, 4 bits each).
#[inline]
fn set_config(port: u32, idx: u32, cnf: u32, mode: u32) {
    let (addr, bit) = cfg_reg(port_regs(port), idx);
    // SAFETY: `addr` is a valid GPIO config register; the caller upholds the
    // free-function safety contract.
    unsafe {
        let v = core::ptr::read_volatile(addr);
        core::ptr::write_volatile(addr, (v & !(0xF << bit)) | ((mode | (cnf << 2)) << bit));
    }
}

/// Atomically drive a port pin high (`high = true`) or low via BSHR/BSXR.
#[inline]
fn drive(port: u32, idx: u32, high: bool) {
    let regs = port_regs(port);
    let (addr, mask) = if idx < 16 {
        (
            regs.bshr.as_ptr(),
            if high { 1 << idx } else { 1 << (idx + 16) },
        )
    } else {
        let k = idx - 16;
        (
            regs.bsxr.as_ptr(),
            if high { 1 << k } else { 1 << (16 + k) },
        )
    };
    // SAFETY: `addr` is a valid set/reset register; the caller upholds the
    // free-function safety contract.
    unsafe { core::ptr::write_volatile(addr, mask) };
}

/// Read the live input value of a GPIO.
///
/// `pin` is a `(port, pin)` tuple (`port`: 0 = A, 1 = B, 2 = C; `pin`:
/// 0..=23). Returns `true` if the pin is high.
///
/// # Safety
///
/// See the free-function safety contract above.
#[inline]
pub unsafe fn get(pin: (u32, u32)) -> bool {
    let (port, idx) = pin;
    assert_pin(port, idx);
    // SAFETY: valid GPIO input register; the caller upholds the safety contract.
    unsafe { (core::ptr::read_volatile(port_regs(port).indr.as_ptr()) >> idx) & 1 != 0 }
}

/// Read the programmed output level of a GPIO (not the live pad state).
///
/// `pin` is a `(port, pin)` tuple (`port`: 0 = A, 1 = B, 2 = C; `pin`:
/// 0..=23).
///
/// # Safety
///
/// See the free-function safety contract above.
#[inline]
pub unsafe fn output(pin: (u32, u32)) -> bool {
    let (port, idx) = pin;
    assert_pin(port, idx);
    // SAFETY: valid GPIO output register; the caller upholds the safety contract.
    unsafe { (core::ptr::read_volatile(port_regs(port).outdr.as_ptr()) >> idx) & 1 != 0 }
}

/// Drive a GPIO output high.
///
/// `pin` is a `(port, pin)` tuple (`port`: 0 = A, 1 = B, 2 = C; `pin`:
/// 0..=23).
///
/// # Safety
///
/// See the free-function safety contract above.
#[inline]
pub unsafe fn set_high(pin: (u32, u32)) {
    let (port, idx) = pin;
    assert_pin(port, idx);
    drive(port, idx, true);
}

/// Drive a GPIO output low.
///
/// `pin` is a `(port, pin)` tuple (`port`: 0 = A, 1 = B, 2 = C; `pin`:
/// 0..=23).
///
/// # Safety
///
/// See the free-function safety contract above.
#[inline]
pub unsafe fn set_low(pin: (u32, u32)) {
    let (port, idx) = pin;
    assert_pin(port, idx);
    drive(port, idx, false);
}

/// Toggle a GPIO output.
///
/// `pin` is a `(port, pin)` tuple (`port`: 0 = A, 1 = B, 2 = C; `pin`:
/// 0..=23).
///
/// # Safety
///
/// See the free-function safety contract above.
#[inline]
pub unsafe fn toggle(pin: (u32, u32)) {
    let (port, idx) = pin;
    assert_pin(port, idx);
    // SAFETY: valid GPIO output register; the caller upholds the safety contract.
    let high =
        unsafe { (core::ptr::read_volatile(port_regs(port).outdr.as_ptr()) >> idx) & 1 != 0 };
    drive(port, idx, !high);
}

/// Set a GPIO output to a specific level.
///
/// `pin` is a `(port, pin)` tuple (`port`: 0 = A, 1 = B, 2 = C; `pin`:
/// 0..=23).
///
/// # Safety
///
/// See the free-function safety contract above.
#[inline]
pub unsafe fn set(pin: (u32, u32), high: bool) {
    unsafe {
        if high {
            set_high(pin);
        } else {
            set_low(pin);
        }
    }
}

/// Configure a GPIO as a push-pull output.
///
/// `pin` is a `(port, pin)` tuple (`port`: 0 = A, 1 = B, 2 = C; `pin`:
/// 0..=23).
///
/// # Safety
///
/// See the free-function safety contract above.
#[inline]
pub unsafe fn into_output(pin: (u32, u32)) {
    let (port, idx) = pin;
    assert_pin(port, idx);
    set_config(port, idx, CNF_OUTPUT_PUSHPULL, MODE_OUTPUT);
}

/// Configure a GPIO as an alternate-function push-pull output.
///
/// I2C and USB-PD automatically switch the driver to open-drain.
///
/// `pin` is a `(port, pin)` tuple (`port`: 0 = A, 1 = B, 2 = C; `pin`:
/// 0..=23).
///
/// # Safety
///
/// See the free-function safety contract above.
#[inline]
pub unsafe fn into_alt_push_pull(pin: (u32, u32)) {
    let (port, idx) = pin;
    assert_pin(port, idx);
    set_config(port, idx, CNF_ALT_PUSHPULL, MODE_OUTPUT);
}

/// Configure a GPIO as a floating input.
///
/// `pin` is a `(port, pin)` tuple (`port`: 0 = A, 1 = B, 2 = C; `pin`:
/// 0..=23).
///
/// # Safety
///
/// See the free-function safety contract above.
#[inline]
pub unsafe fn into_input(pin: (u32, u32)) {
    let (port, idx) = pin;
    assert_pin(port, idx);
    set_config(port, idx, CNF_INPUT_FLOATING, MODE_INPUT);
}

/// Configure a GPIO as a pull-up input.
///
/// `pin` is a `(port, pin)` tuple (`port`: 0 = A, 1 = B, 2 = C; `pin`:
/// 0..=23).
///
/// # Safety
///
/// See the free-function safety contract above.
#[inline]
pub unsafe fn into_input_pullup(pin: (u32, u32)) {
    let (port, idx) = pin;
    assert_pin(port, idx);
    set_config(port, idx, CNF_INPUT_PULL, MODE_INPUT);
    // SAFETY: valid GPIO output register; the caller upholds the safety contract.
    unsafe {
        let addr = port_regs(port).outdr.as_ptr();
        core::ptr::write_volatile(addr, core::ptr::read_volatile(addr) | (1 << idx));
    }
}

/// Configure a GPIO as a pull-down input.
///
/// Note: only PA0..=PA15 and PC16..=PC17 support a pull-down resistor.
///
/// `pin` is a `(port, pin)` tuple (`port`: 0 = A, 1 = B, 2 = C; `pin`:
/// 0..=23).
///
/// # Safety
///
/// See the free-function safety contract above.
#[inline]
pub unsafe fn into_input_pulldown(pin: (u32, u32)) {
    let (port, idx) = pin;
    assert_pin(port, idx);
    set_config(port, idx, CNF_INPUT_PULL, MODE_INPUT);
    // SAFETY: valid GPIO output register; the caller upholds the safety contract.
    unsafe {
        let addr = port_regs(port).outdr.as_ptr();
        core::ptr::write_volatile(addr, core::ptr::read_volatile(addr) & !(1 << idx));
    }
}

/// Configure a GPIO as an analog input.
///
/// `pin` is a `(port, pin)` tuple (`port`: 0 = A, 1 = B, 2 = C; `pin`:
/// 0..=23).
///
/// # Safety
///
/// See the free-function safety contract above.
#[inline]
pub unsafe fn into_analog(pin: (u32, u32)) {
    let (port, idx) = pin;
    assert_pin(port, idx);
    set_config(port, idx, CNF_INPUT_ANALOG, MODE_INPUT);
}
